BEGIN;

SET LOCAL standard_conforming_strings = on;

INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷84·晋少帝本纪·开运二年十月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7fdbc991f6904ba3ca54b43df9788457ad6b8e5f/content/books/zizhi-tongjian/vol-285/year-0945/part-02/sources/library/jiuwudaishi-084-945-october/source.txt", "note": "《旧五代史》卷84·晋少帝本纪·开运二年十月，段落 jiu-wudaishi-205deb4a7860-p002030；已核卷号传主，电子本及异文待纸本校核。", "id": "8139a959-611d-5870-a25b-baf4dfd10ed0"}, {"title": "宋史·卷277·慎知礼传·父慎温其", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7fdbc991f6904ba3ca54b43df9788457ad6b8e5f/content/books/zizhi-tongjian/vol-285/year-0945/part-02/sources/library/songshi-277-shen-wenqi/source.txt", "note": "《宋史》卷277·慎知礼传·父慎温其，段落 songshi-9c6e46fee832-p059490；已核卷号传主，电子本及异文待纸本校核。", "id": "bf6bf384-97d4-584e-b83e-105c4caeaf5a"}, {"title": "资治通鉴·卷285·后晋纪六·开运二年十一月至十二月及后续", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7fdbc991f6904ba3ca54b43df9788457ad6b8e5f/content/books/zizhi-tongjian/vol-285/year-0945/part-02/sources/library/tongjian-285-945-november-december/source.txt", "note": "《资治通鉴》卷285·后晋纪六·开运二年十一月至十二月及后续，段落 zizhi-tongjian-a63549944a71-p003384；已核卷号传主，电子本及异文待纸本校核。", "id": "7f3abe80-c419-5cfb-87b7-588ae233b38c"}, {"title": "新五代史·卷67·吴越世家·钱弘佐杀杜昭达阚璠", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7fdbc991f6904ba3ca54b43df9788457ad6b8e5f/content/books/zizhi-tongjian/vol-285/year-0945/part-02/sources/library/xinwudaishi-067-du-kan-deaths/source.txt", "note": "《新五代史》卷67·吴越世家·钱弘佐杀杜昭达阚璠，段落 xin-wudaishi-b08f244b9241-p003372；已核卷号传主，电子本及异文待纸本校核。", "id": "2a36fee3-0910-53cf-823a-23378d20f39c"}, {"title": "新五代史·卷74·四夷附录第三·高丽王建王武", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7fdbc991f6904ba3ca54b43df9788457ad6b8e5f/content/books/zizhi-tongjian/vol-285/year-0945/part-02/sources/library/xinwudaishi-074-goryeo/source.txt", "note": "《新五代史》卷74·四夷附录第三·高丽王建王武，段落 xin-wudaishi-b08f244b9241-p003665；已核卷号传主，电子本及异文待纸本校核。", "id": "66d6f675-97a8-54f9-bad1-6273d2d4efbf"}, {"title": "资治通鉴·卷285·后晋纪六·开运二年八月至十一月及追述", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/e77e2ab2ec0aa76443441349e3b3533923c10437/content/books/zizhi-tongjian/vol-285/year-0945/part-01/sources/library/tongjian-285-945-august-november/source.txt", "note": "《资治通鉴》卷285·后晋纪六·开运二年八月至十一月及追述，段落 zizhi-tongjian-a63549944a71-p003383；已核卷号与传主，电子本及异文待纸本校核。", "id": "96d6ca1f-263a-53b6-ab58-791ddc7e8727"}, {"title": "新五代史·卷9·晋本纪第九·出帝开运二年", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ac10110d193f69ce3499423e4fa4db294584e2ff/content/books/zizhi-tongjian/vol-284/year-0945/part-01/sources/library/xinwudaishi-009-945/source.txt", "note": "《新五代史》卷9·晋本纪第九·出帝开运二年，段落 xin-wudaishi-b08f244b9241-p000336；已核上下文及传主，纸本及异文待核。", "id": "e3160060-6159-5733-9a3f-cd13016527db"}, {"title": "新五代史·卷68·闽世家·王继昌及卓俨明（后文未在本批提前处理）", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/74486f99392b820f87f1b0c58501ef7c8c04d896/content/books/zizhi-tongjian/vol-284/year-0945/part-03/sources/library/xinwudaishi-068-li-ren-da/source.txt", "note": "《新五代史》卷68·闽世家·王继昌及卓俨明（后文未在本批提前处理），段落 xin-wudaishi-b08f244b9241-p003414；上下文、卷界及传主已校核，纸本及异文待核。", "id": "4c007e7d-1965-54c8-99ae-fa57eab6e1a4"}, {"title": "旧五代史·卷84·晋少帝本纪·开运二年九月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/e77e2ab2ec0aa76443441349e3b3533923c10437/content/books/zizhi-tongjian/vol-285/year-0945/part-01/sources/library/jiuwudaishi-084-945-september/source.txt", "note": "《旧五代史》卷84·晋少帝本纪·开运二年九月，段落 jiu-wudaishi-205deb4a7860-p002029；已核卷号与传主，电子本及异文待纸本校核。", "id": "ca9d8f31-8192-544a-bc5f-23cbf5942e54"}, {"title": "新五代史·卷65·南汉世家·刘晟乾和三年", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/e77e2ab2ec0aa76443441349e3b3533923c10437/content/books/zizhi-tongjian/vol-285/year-0945/part-01/sources/library/xinwudaishi-065-hongya-death/source.txt", "note": "《新五代史》卷65·南汉世家·刘晟乾和三年，段落 xin-wudaishi-b08f244b9241-p003283；已核卷号与传主，电子本及异文待纸本校核。", "id": "6d196b4f-4d62-5838-ad21-786fb0df513d"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "张彦泽", "aliases": ["張彥澤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，938年任镇国军节度使，在华州截击并杀死东行的凤翔叛军。生卒年本段未载。", "biography": null, "status": "draft", "id": "194d0f9a-3b17-5635-9741-dffc983ee32e"}, {"name": "刘弘熙", "aliases": ["劉弘熙", "刘洪熙", "劉洪熙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘熙，获封王爵之子。", "biography": null, "status": "draft", "id": "b67079e8-6ec8-5150-9451-5b3ce7983fec"}, {"name": "刘思潮", "aliases": ["劉思潮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉力士。943年在刘弘熙安排下，由陈道庠召入晋王府练习手搏；随后参与杀死刘弘度，刘弘熙即位后受到赏赐。《新五代史》还记刘思潮等获封功臣。生卒年尚未核。", "biography": null, "status": "draft", "id": "d7493fd7-d448-5c67-8a8d-eb273df31b0a"}, {"name": "林少强", "aliases": ["林少強", "林少彊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉力士，943年与刘思潮等在晋王府练习手搏。《资治通鉴》作林少强，《新五代史》作林少彊。与林少良同姓名相近，但本段未明确亲属关系，暂不建兄弟关系。生卒年尚未核。", "biography": null, "status": "draft", "id": "9f17dd1c-9ee9-595e-a653-d5395d3ee4d8"}, {"name": "林少良", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉力士，943年与刘思潮等在晋王府练习手搏。与林少强同姓名相近，但本段未明确亲属关系，暂不建兄弟关系。生卒年尚未核。", "biography": null, "status": "draft", "id": "ad7835a8-e59d-5074-8319-bb08ffa95cda"}, {"name": "何昌廷", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉力士，943年在刘弘熙安排下，由陈道庠召入晋王府练习手搏。史书将他列于五名力士中，本段未逐一说明他在杀死刘弘度时的动作。生卒年尚未核。", "biography": null, "status": "draft", "id": "5b94ec77-7dd9-5980-b1b2-596ce866c6d3"}, {"name": "王翷", "aliases": ["王翻"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉右仆射兼西御院使。刘岩病重时与他商议把刘弘度、刘弘熙调往外地，立刘弘昌；计划经萧益劝阻而停止。《新五代史》同次谋划写王翻，姓名异字保留。", "biography": null, "status": "draft", "id": "7d3d5c3d-e1e1-5028-a38b-e128bffa5ef0"}, {"name": "宋氏（南唐李昪后）", "aliases": ["宋氏（李昪后）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李昪的皇后。937年被立为皇后，939年与李昪为李氏父母服丧。个人名字及生卒年本次未核。", "biography": null, "status": "draft", "id": "87d8df9d-227e-5ea6-9284-514b5a1aebcd"}, {"name": "王延政", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王延政，都教练使、赴建州抚慰者。", "biography": null, "status": "draft", "id": "83601670-f3dc-5559-b599-e39bda91eb6c"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "杨思恭", "aliases": ["楊思恭"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "建阳人，王延政属下的节度巡官。943年王延政建殷后任兵部尚书，不久升仆射、录军国事。史书记他加重田亩山泽及鱼盐蔬果税负，记载当时人称他为杨剥皮。生卒年尚未核。", "biography": null, "status": "draft", "id": "588de476-95b1-534e-af0e-97b68a1f83a0"}, {"name": "王崇文", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐百胜军节度使。945年建州陷落后受任永安节度使，《资治通鉴》记他治理宽简，建州百姓渐安。生卒年本段未载。", "biography": null, "status": "draft", "id": "e00c8607-6426-5398-b911-e9eba22c7740"}, {"name": "王建（高丽）", "aliases": ["王建（高麗）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271龙德二年条所见人物：王建（高丽）。", "biography": null, "status": "draft", "id": "1a4ad018-a488-54b2-bbfa-f1b22e5b2245"}, {"name": "袜啰", "aliases": ["襪囉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "史书称为胡僧，曾替高丽王建向石敬瑭请求合攻契丹以取回渤海，后来又向石重贵进言。郭仁遇实地出使后对其所述高丽兵力作出不同判断。生卒、族属与其他译名本段未载。", "biography": null, "status": "draft", "id": "9a66c2e5-0901-510d-9e59-406914b21f32"}, {"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "石重贵", "aliases": ["石重貴"], "era": "五代十国", "birth_year": 914, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：石重贵，被叙侄子及养子身份者。", "biography": null, "status": "draft", "id": "2741e60a-9bf9-56a7-b30d-3db439caa139"}, {"name": "王武（高丽）", "aliases": ["王武（高麗）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "高丽王建之子。父亲去世后自称权知国事，上表告丧；945年十一月戊戌获得后晋所授大义军使、高丽王。郭仁遇出使要求攻契丹，返回后王武又以其他理由推辞。其生卒年本次未核，不凭同名合并其他王武。", "biography": null, "status": "draft", "id": "4fd76519-01f6-534d-9c1e-f58e8521c565"}, {"name": "郭仁遇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋通事舍人。945年奉命出使高丽，要求王武攻契丹；到当地后认为高丽兵力很弱、不能与契丹为敌，随后返回。生卒年本段未载。", "biography": null, "status": "draft", "id": "246bbfe4-dfca-5279-9f00-75640b490894"}, {"name": "钱弘佐", "aliases": ["錢弘佐"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲许氏。939年条下的王室家属追述提及他，出生年份本句未载。", "biography": null, "status": "draft", "id": "0d604e68-f71f-5263-9e8f-80de6e9feb32"}, {"name": "杜昭达", "aliases": ["杜昭達"], "era": "五代十国", "birth_year": null, "death_year": 945, "description": "杜建徽的孙子，吴越内都监使。曾与阚璠接受程昭悦的钱财结交；945年十一月乙卯被钱弘佐杀死。《资治通鉴》将谋立钱仁俊的说法记为程昭悦诬告和制造证据，未当作确实谋反。出生年本段未载。", "biography": null, "status": "draft", "id": "3cff8271-427f-576f-b0d2-bf245c04ff8d"}, {"name": "阚璠", "aliases": ["闞璠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "明州人，吴越上统军使。钱弘佐初立时，史书说他排斥异己，钱弘佐不能制约；943年章德安、李文庆被贬后，他与胡进思更为专横。人物评价按史书归属保留，生卒年尚未核。", "biography": null, "status": "draft", "id": "b40418a5-918a-53c4-a5aa-4618d7fc7cd6"}, {"name": "杜建徽", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷263天复二年条所见人物：杜建徽。", "biography": null, "status": "draft", "id": "dc45e504-5420-5b40-bf71-bba443a606f4"}, {"name": "程昭悦", "aliases": ["程昭悅"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱塘富人，通过财物结交杜昭达、阚璠，得以接近钱弘佐。后来谋排阚璠，诬告阚璠、杜昭达拥立钱仁俊，使两人遇害、钱仁俊失官被囚，并清除百余权位与自己相当或被自己忌恨的人。生卒年本段未载。", "biography": null, "status": "draft", "id": "4dcc2f3e-2f3d-5dcd-b573-598392035d56"}, {"name": "胡进思", "aliases": ["胡進思"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "湖州人，吴越右统军使。943年条下记章德安与李文庆被贬后，史书称他与阚璠更加专横。生卒年尚未核。", "biography": null, "status": "draft", "id": "4f56160f-2b15-5a0c-9fa8-9523947bb1df"}, {"name": "钱仁俊", "aliases": ["錢仁俊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：钱仁俊，从子、受遣告谕者。", "biography": null, "status": "draft", "id": "8ba65976-a158-523f-a631-fac69d75de34"}, {"name": "慎温其", "aliases": ["慎溫其"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "衢州人，钱仁俊故吏。被程昭悦拷打逼迫作证时坚持不屈，得到钱弘佐赏识，擢为国官。《宋史》慎知礼传记其父温其有词学，后仕钱俶至元帅府判官。生卒年未载。", "biography": null, "status": "draft", "id": "36b637ee-b8ae-5066-8300-848907f0cd86"}]'::jsonb)
